-- irender-cc-amberfield (researched)
UPDATE businesses SET description = 'iRender cc is an official SketchUp Gold Reseller in South Africa with more than 25 years of experience and over 1,400 licences deployed, selling and supporting SketchUp software for architects, interior designers, landscape architects and construction professionals. The company handles local ZAR invoicing on annual subscriptions, letting clients pay by EFT or credit card without dealing with a foreign billing currency.

Its range spans an entry-level, web-based tier suited to hobbyists and light use through to a full desktop Pro edition with layout documentation tools, extension warehouse integration and Trimble Connect collaboration, alongside further Studio and advanced workflow tiers for larger practices. iRender also offers a free seven-day trial so customers can test the software before committing to a subscription. Based in Amberfield, Centurion, and trading since 2001, the company serves design and construction professionals across South Africa needing SketchUp licensed and supported locally.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://www.irender.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'irender-cc-amberfield' AND description = 'iRender cc is an official SketchUp Gold Reseller in South Africa, selling and supporting SketchUp software licences for architects, interior designers, landscape architects and construction professionals, with local ZAR invoicing and support since 2001.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- jean-lle-granite-east-lynne (researched)
UPDATE businesses SET description = 'Jeanelle Granite is a granite and stone supplier in East Lynne, established on 23 January 2006 with an original focus on fabricating and installing kitchen units and built-in cupboards. The business opened a dedicated granite division in 2009, and as its focus on stone grew, moved to working solely with granite, quartz and marble surfaces for kitchen tops and cupboards.

Its engineered quartz range includes well-known brands such as Caesarstone, Pro Quartz and Eezi Quartz, while its granite and marble are sourced both locally and from countries including Israel, Brazil, India, Turkey and Namibia. Services cover on-site measure-ups, cut-outs for new or replacement appliances, and full fabrication and installation of finished surfaces. Based in East Lynne, Pretoria, Jeanelle Granite serves homeowners and renovators needing granite, quartz, marble or porcelain countertops cut, polished and installed from a single local workshop.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://www.jeanelle.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'jean-lle-granite-east-lynne' AND description = 'A granite and stone supplier in East Lynne operating since 2006, fabricating and installing granite, marble, engineered quartz and porcelain kitchen countertops and built-in cupboards, sourcing stone from Israel, Brazil, India, Turkey and Namibia.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- jetline-montana-montana-gardens (researched)
